export function ComponentApi({
  label = "{{label}}",
  size = "{{size}}",
  disabled = {{disabled}},
  accent = "{{accent}}",
}) {
  const pad = { sm: "6px 12px", md: "10px 18px", lg: "14px 26px" }[size];
  const fontSize = { sm: 12, md: 14, lg: 17 }[size];
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, maxWidth: 300, boxSizing: "border-box", display: "flex", flexDirection: "column", gap: 16 }}>
      <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 12 }}>
        <tbody>
          <tr><th style={{ textAlign: "left", padding: "5px 8px", color: "#24143099" }}>prop</th><th style={{ textAlign: "left", padding: "5px 8px", color: "#24143099" }}>value</th></tr>
          <tr><td style={{ padding: "5px 8px" }}>label</td><td style={{ padding: "5px 8px" }}>"{label}"</td></tr>
          <tr><td style={{ padding: "5px 8px" }}>size</td><td style={{ padding: "5px 8px" }}>"{size}"</td></tr>
          <tr><td style={{ padding: "5px 8px" }}>disabled</td><td style={{ padding: "5px 8px" }}>{String(disabled)}</td></tr>
        </tbody>
      </table>
      <button type="button" disabled={disabled} style={{ background: accent, border: "none", borderRadius: 8, color: "#241430", fontWeight: 600, padding: pad, fontSize, cursor: disabled ? "not-allowed" : "pointer", opacity: disabled ? .4 : 1, width: "fit-content" }}>{label}</button>
    </div>
  );
}
